import 'package:flutter/material.dart';

class ProgramPoint {
  final String title;
  final String description;
  final String detailedContent;
  final IconData icon;

  const ProgramPoint({
    required this.title,
    required this.description,
    required this.detailedContent,
    required this.icon,
  });
}

class CriticalQuestion {
  final String question;
  final String analysis;
  final String detailedAnalysis;
  final String category; // 'economic', 'social', 'impact'

  const CriticalQuestion({
    required this.question,
    required this.analysis,
    required this.detailedAnalysis,
    required this.category,
  });
}

class PoliticalParty {
  final String name;
  final String abbreviation;
  final String leader;
  final String ideology;
  final String shortDescription;
  final Color primaryColor;
  final Color secondaryColor;
  final IconData icon;
  final String positioning; // 'Extrême gauche', 'Gauche', 'Centre', 'Droite', 'Extrême droite'
  final List<ProgramPoint> programPoints;
  final List<CriticalQuestion> criticalQuestions;
  final String summary;
  final String logoAsset;    // Path to party logo in assets/images/
  final String leaderAsset;  // Path to leader face in assets/images/

  const PoliticalParty({
    required this.name,
    required this.abbreviation,
    required this.leader,
    required this.ideology,
    required this.shortDescription,
    required this.primaryColor,
    required this.secondaryColor,
    required this.icon,
    required this.positioning,
    required this.programPoints,
    required this.criticalQuestions,
    required this.summary,
    required this.logoAsset,
    required this.leaderAsset,
  });
}

